// Command relaypack-fixtures generates the FRP-1 seed test-vector
// corpus for the RelayPack profile validator.
//
// Output goes to specs/test-vectors/relaypack/. Each vector is a
// pair: <name>.sbp (the sealed archive) and <name>.expected.json
// (the per-phase expected validator outcome, generated by
// replaying Validate against the just-built bundle). These two
// files are the FRP-1 spec contract and ARE tracked in git.
//
// A pretty-printed <name>.manifest.json companion is written ONLY
// when -emit-manifest-json is passed. Those files are review-only
// helpers, regenerable on demand, NOT part of the FRP-1 spec
// contract, NOT tracked in git (see .gitignore), and trigger
// spurious secret-scanner alerts on the test publisher key
// fingerprint, which is why they default to off.
//
// Determinism: the binary uses a fixed seed-derived publisher
// keypair and fixed RFC3339 timestamps so the output bytes are
// stable across runs. Ed25519 signatures are deterministic per
// (key, message); pinning the timestamps in the manifest pins the
// message and therefore pins the signature.
//
// Usage (from repo root):
//
//	cd publisher && go run ./cmd/relaypack-fixtures
//	cd publisher && go run ./cmd/relaypack-fixtures -emit-manifest-json
package main

import (
	"bytes"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"

	"daal/bundle-go/bundle"
	relaypack "daal/bundle-go/relaypackvalidate"
)

var emitManifestJSON = flag.Bool(
	"emit-manifest-json",
	false,
	"also write <name>.manifest.json (pretty-printed manifest, review-only, untracked, not part of the FRP-1 spec contract)",
)

const (
	pinnedValidFrom  = "2026-01-01T00:00:00Z"
	pinnedValidUntil = "2027-01-01T00:00:00Z"
	pinnedCreatedAt  = "2026-01-01T00:00:00Z"
	pinnedExpiresAt  = "2027-01-01T00:00:00Z"
)

// outDir resolves to specs/test-vectors/relaypack relative to the
// publisher module root (the binary is run from publisher/).
func outDir() string {
	wd, err := os.Getwd()
	if err != nil {
		log.Fatalf("cwd: %v", err)
	}
	return filepath.Join(wd, "..", "specs", "test-vectors", "relaypack")
}

// deterministicKeypair derives a pinned Ed25519 keypair from a
// fixed seed. NEVER use this key for anything but test fixtures.
func deterministicKeypair() (ed25519.PublicKey, ed25519.PrivateKey) {
	seed := sha256.Sum256([]byte("daal-frp-1-fixture-seed"))
	priv := ed25519.NewKeyFromSeed(seed[:])
	pub := priv.Public().(ed25519.PublicKey)
	return pub, priv
}

func mustMarshal(v any) []byte {
	b, err := json.Marshal(v)
	if err != nil {
		log.Fatalf("marshal: %v", err)
	}
	return b
}

type expectedOutcome struct {
	Phase    string   `json:"phase"`
	Pass     bool     `json:"pass"`
	ErrCode  string   `json:"error_code,omitempty"`
	Warnings []string `json:"warnings,omitempty"` // codes only, sorted
}

type expectedFile struct {
	Vector   string            `json:"vector"`
	Purpose  string            `json:"purpose"`
	Outcomes []expectedOutcome `json:"outcomes"`
}

func writeFile(path string, body []byte) {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		log.Fatalf("mkdir %s: %v", path, err)
	}
	if err := os.WriteFile(path, body, 0o644); err != nil {
		log.Fatalf("write %s: %v", path, err)
	}
}

// buildVector seals a manifest into a .sbp, runs the validator
// against each phase, and writes all three artefacts.
func buildVector(name, purpose string, m bundle.Manifest, profiles map[string][]byte) {
	pub, priv := deterministicKeypair()
	m.Publisher.KeyFingerprintHex = bundle.PublisherFingerprint(pub).Hex
	if profiles == nil {
		profiles = map[string][]byte{
			"profiles/route.json": []byte(`{"type":"direct"}`),
		}
	}

	dir := outDir()

	// 1. Sealed .sbp (the FRP-1 spec contract; tracked in git).
	//    Use the deterministic builder: ZIP entries are sorted by
	//    name, mtime is zeroed, and Store (no compression) is used,
	//    which makes the output byte-stable across regenerations.
	data, err := bundle.BuildSignedBundleDeterministic(m, profiles, nil, pub, priv)
	if err != nil {
		log.Fatalf("%s: build sealed: %v", name, err)
	}
	writeFile(filepath.Join(dir, name+".sbp"), data)

	// 2. Optional pretty-printed manifest for human review.
	//    Off by default (see -emit-manifest-json). Untracked.
	if *emitManifestJSON {
		manifestJSON, err := json.MarshalIndent(m, "", "  ")
		if err != nil {
			log.Fatalf("%s: marshal: %v", name, err)
		}
		writeFile(filepath.Join(dir, name+".manifest.json"), manifestJSON)
	}

	// 3. Expected outcomes per phase.
	expected := expectedFile{Vector: name, Purpose: purpose}
	phases := []relaypack.Phase{relaypack.PhaseV15, relaypack.PhaseV16, relaypack.PhasePostV2}
	for _, ph := range phases {
		opts := relaypack.ValidateOpts{Phase: ph}
		if ph == relaypack.PhasePostV2 {
			// Allow client_desync at PostV2 so the modifier-rejected
			// vector flips to OK.
			opts.AllowedModifierKinds = map[string]bool{
				"client_desync": true,
				"tls_fragment":  true,
			}
		}
		// Re-parse from the sealed bytes so we exercise the full
		// flow, not the in-memory struct.
		b, err := bundle.ParseSBP(bytes.NewReader(data), int64(len(data)))
		if err != nil {
			log.Fatalf("%s: parse sealed: %v", name, err)
		}
		report, vErr := relaypack.Validate(b, opts)
		out := expectedOutcome{Phase: string(ph), Pass: vErr == nil}
		if vErr != nil {
			if ve, ok := vErr.(*relaypack.ValidationError); ok {
				out.ErrCode = string(ve.Code)
			} else {
				out.ErrCode = vErr.Error()
			}
		}
		for _, w := range report.Warnings {
			out.Warnings = append(out.Warnings, string(w.Code))
		}
		expected.Outcomes = append(expected.Outcomes, out)
	}
	body, err := json.MarshalIndent(expected, "", "  ")
	if err != nil {
		log.Fatalf("%s: marshal expected: %v", name, err)
	}
	writeFile(filepath.Join(dir, name+".expected.json"), body)
	fmt.Printf("ok  %s\n", name)
}

func basePub() bundle.PublisherInfo {
	return bundle.PublisherInfo{
		Name:         "Daal FRP-1 Fixture Publisher",
		KeyCreatedAt: pinnedCreatedAt,
		TrustClass:   "unknown",
	}
}

func baseBundle(id string) bundle.BundleInfo {
	return bundle.BundleInfo{
		ID:             id,
		Type:           "provider",
		CreatedAt:      pinnedCreatedAt,
		ExpiresAt:      pinnedExpiresAt,
		SupersedesKeys: []string{},
	}
}

// route returns a base RouteManifestEntry; callers patch
// FamilySpecificConfig and TransportFamily as needed.
func route(id, family string) bundle.RouteManifestEntry {
	return bundle.RouteManifestEntry{
		ID:              id,
		ScarcityClass:   "normal",
		TransportFamily: family,
		ConfigPath:      "profiles/route.json",
		ValidFrom:       pinnedValidFrom,
		ValidUntil:      pinnedValidUntil,
	}
}

// rpEntry packs a RelayPackEntry into a FamilySpecificConfig blob,
// optionally adding sibling keys (e.g. legacy shared_risk_tags).
//
// FRP-8: cdn_fronted entries auto-include a passing
// _cdn_attestation unless the test supplied one in `extras`. This
// preserves the V1.6 positive-path corpus across the RP022/RP023
// validator widening landed in commit 4/8.
func rpEntry(e bundle.RelayPackEntry, extras map[string]any) json.RawMessage {
	m := map[string]any{"_relaypack": e}
	if _, hasAtt := extras["_cdn_attestation"]; !hasAtt && e.ExposureMode == "cdn_fronted" {
		m["_cdn_attestation"] = bundle.CDNAttestation{
			OriginCAFingerprint: "abababababababababababababababababababababababababababababababab",
			AOPEnabled:          true,
			FirewallID:          "fw-frp1-fixture",
			DNSOnlyPresent:      false,
		}
	}
	for k, v := range extras {
		m[k] = v
	}
	return mustMarshal(m)
}

// ---- vectors ---------------------------------------------------

func directVPSMinimal() {
	rp := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"public_ip:5.75.0.1", "public_port:tcp443"},
		OriginRiskTags:   []string{},
	}
	r1 := route("r1", "vless-reality")
	r1.FamilySpecificConfig = rpEntry(rp, nil)
	r2 := route("r2", "naive")
	r2.FamilySpecificConfig = rpEntry(rp, nil)

	m := bundle.Manifest{
		SpecVersion: 3,
		Publisher:   basePub(),
		Bundle:      baseBundle("frp1-direct-vps-minimal"),
		Routes:      []bundle.RouteManifestEntry{r1, r2},
		RelayPack: &bundle.RelayPack{
			RelayPackID: "rp-frp1-direct-vps-minimal",
			SharedRiskGraph: []bundle.SharedRiskEdge{
				{Tag: "public_ip:5.75.0.1", Members: []string{"r1", "r2"}},
				{Tag: "public_port:tcp443", Members: []string{"r1", "r2"}},
			},
		},
	}
	buildVector("direct-vps-minimal",
		"Two direct_vps vps-native candidates with no public-surface diversity.",
		m, nil)
}

func directVPSWithSNI() {
	rp := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags: []string{
			"public_ip:5.75.0.1",
			"public_port:tcp443",
			"public_domain:host.example.com",
			"host:host.example.com",
			"sni:www.microsoft.com",
		},
		OriginRiskTags: []string{},
	}
	r1 := route("r1", "vless-reality")
	r1.FamilySpecificConfig = rpEntry(rp, nil)
	r2 := route("r2", "websocket-tls")
	rp2 := rp
	rp2.PublicRiskTags = []string{"public_ip:1.2.3.4", "public_port:tcp443", "public_domain:other.example.com"}
	r2.FamilySpecificConfig = rpEntry(rp2, nil)

	m := bundle.Manifest{
		SpecVersion: 3,
		Publisher:   basePub(),
		Bundle:      baseBundle("frp1-direct-vps-with-sni"),
		Routes:      []bundle.RouteManifestEntry{r1, r2},
		RelayPack: &bundle.RelayPack{
			RelayPackID:     "rp-frp1-direct-vps-with-sni",
			SharedRiskGraph: []bundle.SharedRiskEdge{},
		},
	}
	buildVector("direct-vps-with-sni",
		"direct_vps candidates carrying public_domain:, host:, and sni: tags (legitimate visible domain on own VPS).",
		m, nil)
}

