func modifierRejected() {
	rp := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"public_ip:5.75.0.1", "public_port:tcp443"},
		OriginRiskTags:   []string{},
		Modifiers: []bundle.Modifier{
			{Kind: "client_desync", Platform: "linux_desktop_only", ProbingRiskClass: "high"},
		},
	}
	r1 := route("r1", "vless-reality")
	r1.FamilySpecificConfig = rpEntry(rp, nil)

	rp2 := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"public_ip:5.75.0.1", "public_port:tcp443"},
		OriginRiskTags:   []string{},
	}
	r2 := route("r2", "naive")
	r2.FamilySpecificConfig = rpEntry(rp2, nil)

	m := bundle.Manifest{
		SpecVersion: 3,
		Publisher:   basePub(),
		Bundle:      baseBundle("frp1-modifier-rejected"),
		Routes:      []bundle.RouteManifestEntry{r1, r2},
		RelayPack: &bundle.RelayPack{
			RelayPackID:     "rp-frp1-modifier-rejected",
			SharedRiskGraph: []bundle.SharedRiskEdge{},
		},
	}
	buildVector("modifier-rejected",
		"Candidate with non-empty modifiers[client_desync]. Rejected at V15/V16 (RP013); accepted at PostV2 only when client_desync is in AllowedModifierKinds.",
		m, nil)
}

