// legacyNonRelayPack: bundle with no _relaypack and no
// Manifest.RelayPack slot. Validator is inert; importer takes
// the legacy path with sentinel-empty RouteRow columns.
func legacyNonRelayPack() {
	r1 := route("r1", "vless-reality")
	r2 := route("r2", "naive")
	m := bundle.Manifest{
		SpecVersion: 1, // pre-FRP-1
		Publisher:   basePub(),
		Bundle:      baseBundle("frp2-legacy-non-relaypack"),
		Routes:      []bundle.RouteManifestEntry{r1, r2},
		// RelayPack: nil — no slot.
	}
	buildVector("legacy-non-relaypack",
		"Bundle with no _relaypack and no Manifest.relay_pack slot. Validator is inert; importer takes legacy path with sentinel-empty RouteRow columns.",
		m, nil)
}

// mixedRelayPackDirectOnly: three direct_vps siblings on one VPS.
// V1.5-positive; demonstrates the single-VPS-multiple-candidates
// shape FRP-2 unblocks.
func mixedRelayPackDirectOnly() {
	rp := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"public_ip:5.75.0.1", "public_port:tcp443"},
		OriginRiskTags:   []string{},
	}
	r1 := route("r1", "vless-reality")
	r1.FamilySpecificConfig = rpEntry(rp, nil)
	r2 := route("r2", "naive")
	r2.FamilySpecificConfig = rpEntry(rp, nil)
	r3 := route("r3", "websocket-tls")
	r3.FamilySpecificConfig = rpEntry(rp, nil)
	m := bundle.Manifest{
		SpecVersion: 3,
		Publisher:   basePub(),
		Bundle:      baseBundle("frp2-mixed-relaypack-direct-only"),
		Routes:      []bundle.RouteManifestEntry{r1, r2, r3},
		RelayPack: &bundle.RelayPack{
			RelayPackID: "rp-frp2-mixed-direct-only",
			SharedRiskGraph: []bundle.SharedRiskEdge{
				{Tag: "public_ip:5.75.0.1", Members: []string{"r1", "r2", "r3"}},
				{Tag: "public_port:tcp443", Members: []string{"r1", "r2", "r3"}},
			},
		},
	}
	buildVector("mixed-relaypack-direct-only",
		"Three direct_vps siblings on a single VPS. V1.5-positive single-VPS multi-candidate shape.",
		m, nil)
}

// mixedRelayPackDirectAndCDN: V1.6 candidate alongside a direct.
// V1.5 importer rejects with RP004 (the cdn_fronted candidate
// fails phase gate).
func mixedRelayPackDirectAndCDN() {
	cdn := bundle.RelayPackEntry{
		ExposureMode:     "cdn_fronted",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"cdn:cloudflare", "public_domain:e.example.com"},
		OriginRiskTags:   []string{"origin_ip:5.75.0.1"},
	}
	d1 := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"public_ip:5.75.0.1", "public_port:tcp443"},
		OriginRiskTags:   []string{},
	}
	d2 := bundle.RelayPackEntry{
		ExposureMode:     "direct_vps",
		FamilyClass:      "vps-native",
		ProbingRiskClass: "low",
		PublicRiskTags:   []string{"public_ip:1.2.3.4", "public_port:tcp443"},
		OriginRiskTags:   []string{},
	}
	r1 := route("r1", "websocket-tls")
	r1.FamilySpecificConfig = rpEntry(cdn, nil)
	r2 := route("r2", "vless-reality")
	r2.FamilySpecificConfig = rpEntry(d1, nil)
	r3 := route("r3", "naive")
	r3.FamilySpecificConfig = rpEntry(d2, nil)
	m := bundle.Manifest{
		SpecVersion: 3,
		Publisher:   basePub(),
		Bundle:      baseBundle("frp2-mixed-relaypack-direct-and-cdn"),
		Routes:      []bundle.RouteManifestEntry{r1, r2, r3},
		RelayPack: &bundle.RelayPack{
			RelayPackID:     "rp-frp2-mixed-direct-and-cdn",
			SharedRiskGraph: []bundle.SharedRiskEdge{},
		},
	}
	buildVector("mixed-relaypack-direct-and-cdn",
		"Mixed cdn_fronted + 2 direct_vps. V1.5 rejects (RP004). V1.6 accepts.",
		m, nil)
}

